<script setup lang="ts">
import { t, locale } from '../i18n'
import { computed, ref, reactive, watch } from 'vue'
import { useRoute } from 'vue-router'
import { LayoutDashboard, CalendarDays, Users, MessageSquare, BookOpenText, ArrowUpLeft, Plus } from 'lucide-vue-next'
import { platforms } from '../data'
import { state, uid, today, dateLabel, occupied, saveSlot, future, storageError, type Doctor, type Slot } from '../operations'
import OpsShell from '../components/OpsShell.vue'
import AppointmentCalendar from '../components/AppointmentCalendar.vue'
const route=useRoute()
const platform=computed(()=>platforms.find(p=>p.slug===route.params.slug))
const tab=ref('overview'), notice=ref(''), query=ref(''), filter=ref('all'), dateFilter=ref(''), doctorFilter=ref(''), editing=ref('')
const scope=computed(()=>platform.value?.slug)
const doctors=computed(()=>state.doctors.filter(d=>!scope.value||d.platform===scope.value))
const slots=computed(()=>state.slots.filter(s=>(!scope.value||s.platform===scope.value)&&(!dateFilter.value||s.date===dateFilter.value)&&(!doctorFilter.value||s.doctor===doctorFilter.value)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))
const bookings=computed(()=>state.bookings.filter(b=>slots.value.some(s=>s.id===b.slot)&&(filter.value==='all'||b.status===filter.value)&&`${b.name} ${b.phone} ${b.id}`.includes(query.value)))
const tickets=computed(()=>state.tickets.filter(t=>(filter.value==='all'||t.status===filter.value)&&`${t.name} ${t.subject} ${t.id}`.includes(query.value)))
const free=computed(()=>slots.value.filter(s=>!occupied(s.id)&&!s.blocked&&future(s)&&state.doctors.find(d=>d.id===s.doctor)?.active).length)
const activeCount=computed(()=>state.bookings.filter(b=>b.status==='confirmed'&&slots.value.some(s=>s.id===b.slot)).length)
const doctorForm=reactive<Doctor>({id:'',platform:'',name:'',specialty:'',bio:'',active:true})
const slotForm=reactive<Slot>({id:'',platform:'',doctor:'',date:today(),time:'09:00',duration:30,mode:'آنلاین',price:350000,blocked:false})
function switchTab(t:string){tab.value=t;filter.value='all';query.value='';notice.value='';dateFilter.value='';doctorFilter.value=''}
watch(()=>route.query.tab,value=>{if(value==='tickets'&&!platform.value)switchTab('tickets')},{immediate:true})
function createCalendarSlot(date:string,time:string,doctor?:string){editSlot();slotForm.date=date;slotForm.time=time;if(doctor)slotForm.doctor=doctor}
function editDoctor(d?:Doctor){Object.assign(doctorForm,d||{id:uid(),platform:scope.value||platforms[0]!.slug,name:'',specialty:'',bio:'',active:true});editing.value='doctor'}
function persistDoctor(){const i=state.doctors.findIndex(d=>d.id===doctorForm.id);if(i<0)state.doctors.push({...doctorForm});else state.doctors[i]={...doctorForm};editing.value='';notice.value='اطلاعات متخصص ذخیره شد.'}
function editSlot(s?:Slot){Object.assign(slotForm,s||{id:uid(),platform:scope.value||platforms[0]!.slug,doctor:doctors.value.find(d=>d.active)?.id||'',date:today(),time:'09:00',duration:30,mode:'آنلاین',price:350000,blocked:false});editing.value='slot';notice.value=''}
function persistSlot(){try{const d=state.doctors.find(d=>d.id===slotForm.doctor);if(!d?.active)throw new Error('یک پزشک فعال انتخاب کنید.');saveSlot({...slotForm,platform:d.platform});editing.value='';notice.value='زمان ویزیت ذخیره شد.'}catch(e){notice.value=(e as Error).message}}
function block(s:Slot){if(occupied(s.id)){notice.value='این زمان رزرو دارد. ابتدا رزرو را لغو کنید.';return}s.blocked=!s.blocked}
function cancel(id:string){if(confirm('رزرو لغو و زمان آن آزاد شود؟')){state.bookings.find(b=>b.id===id)!.status='cancelled';notice.value='رزرو لغو شد و زمان آزاد است.'}}
const doctorName=(id:string)=>state.doctors.find(d=>d.id===id)?.name||'—'
const slotOf=(id:string)=>state.slots.find(s=>s.id===id)!
const statusLabel=(s:string)=>({confirmed:'تأییدشده',completed:'انجام‌شده',cancelled:'لغوشده',new:'جدید',review:'در حال بررسی',closed:'بسته‌شده'}[s]||s)
</script>
<template>
<OpsShell :platform="platform" :tab="tab" @tab="switchTab"><div :key="tab" class="ops-tab-content"><div class="ops-heading"><div><span class="kicker">{{ t("مدیریت") }} {{ t(platform?.eyebrow||'اکوسیستم سلامت') }}</span><h1>{{ t(({overview:'همه‌چیز، در یک نگاه.',slots:'تقویم و زمان‌بندی',bookings:'نوبت‌های مراجعان',doctors:'متخصصان',tickets:'صندوق ارتباط با ما'} as Record<string,string>)[tab]) }}</h1><p>{{ t("برنامه‌ها، ارتباط‌ها و مسیر مراقبت را مدیریت کنید.") }}</p></div><button v-if="tab==='slots'||tab==='doctors'" class="button button-primary" @click="tab==='slots'?editSlot():editDoctor()"><Plus :size="18"/>{{ t(tab==='slots'?'زمان جدید':'متخصص جدید') }}</button></div>
<div v-if="notice||storageError" class="ops-notice" role="status">{{t(storageError||notice)}}</div>
<template v-if="tab==='overview'"><div class="ops-stats"><article><span>{{ t(platform?'نوبت‌های تأییدشده':'پلتفرم‌های فعال') }}</span><b>{{platform?activeCount:platforms.length}}</b><small>{{ t(platform?'در انتظار برگزاری':'زیر یک چتر مشترک') }}</small></article><article><span>{{ t(platform?'زمان‌های آزاد':'پیام‌های جدید') }}</span><b>{{platform?free:state.tickets.filter(ticket=>ticket.status==='new').length}}</b><small>{{ t(platform?'قابل رزرو توسط مراجعان':'در انتظار بررسی') }}</small></article><article><span>{{ t("متخصصان فعال") }}</span><b>{{doctors.filter(d=>d.active).length}}</b><small>{{ t("در مجموعه شما") }}</small></article></div><section class="ops-panel"><h2>{{ t(platform?'مدیریت مسیر ویزیت':'دسترسی به پلتفرم‌ها') }}</h2><div v-if="!platform" class="ops-platforms"><RouterLink v-for="p in platforms" :key="p.slug" :to="`/admin/platforms/${p.slug}`"><strong>{{ t(p.name) }}</strong><span>{{ t(p.eyebrow) }}</span><ArrowUpLeft :size="20"/></RouterLink></div><div v-else class="ops-quick"><button @click="switchTab('slots')">{{ t("تقویم و زمان‌های خالی ←") }}</button><button @click="switchTab('bookings')">{{ t("بررسی رزروها ←") }}</button><button @click="switchTab('doctors')">{{ t("ویرایش اطلاعات متخصصان ←") }}</button></div></section></template>
<section v-if="tab==='overview'" class="ops-panel"><div class="ops-panel-title"><h2>نوبت‌های پیش رو</h2><span>آخرین برنامه‌های ثبت‌شده در مجموعه</span></div><div class="ops-upcoming"><article v-for="b in state.bookings.filter(b=>b.status==='confirmed'&&slots.some(s=>s.id===b.slot&&future(s))).slice(0,5)" :key="b.id"><span class="upcoming-time">{{slotOf(b.slot).time}}</span><div><strong>{{b.name}}</strong><small>{{doctorName(slotOf(b.slot).doctor)}} · {{dateLabel(slotOf(b.slot).date)}}</small></div><span class="status-pill">تأییدشده</span></article></div><p v-if="!activeCount" class="empty-state">نوبت تأییدشده‌ای در این مجموعه ثبت نشده است.</p></section>
<template v-if="tab==='slots'||tab==='bookings'"><div v-if="tab==='bookings'" class="ops-filters"><label>{{ t("روز") }}<input v-model="dateFilter" type="date"/></label><label>{{ t("متخصص") }}<select v-model="doctorFilter"><option value="">{{ t("همه متخصصان") }}</option><option v-for="d in doctors" :key="d.id" :value="d.id">{{ t(d.name) }}</option></select></label><label v-if="tab==='bookings'">{{ t("وضعیت") }}<select v-model="filter"><option value="all">{{ t("همه وضعیت‌ها") }}</option><option value="confirmed">{{ t("تأییدشده") }}</option><option value="completed">{{ t("انجام‌شده") }}</option><option value="cancelled">{{ t("لغوشده") }}</option></select></label><label v-if="tab==='bookings'">{{ t("جست‌وجو") }}<input v-model="query" :placeholder="t('نام، تلفن یا کد پیگیری')"/></label><button class="button button-ghost" @click="dateFilter='';doctorFilter='';filter='all';query=''">{{ t("پاک کردن فیلترها") }}</button></div>
<AppointmentCalendar v-if="tab==='slots' && platform" :platform="platform.slug" @create="createCalendarSlot" @edit="editSlot"/>
<section v-else class="ops-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>{{ t("مراجع / کد پیگیری") }}</th><th>{{ t("متخصص و زمان") }}</th><th>{{ t("نوع / هزینه") }}</th><th>{{ t("توضیح") }}</th><th>{{ t("وضعیت / عملیات") }}</th></tr></thead><tbody><tr v-for="b in bookings" :key="b.id"><td><span>{{b.name}}<br>{{b.phone}}<br><small>{{b.id.slice(0,8)}}</small></span></td><td>{{ t(doctorName(slotOf(b.slot).doctor)) }}<br>{{dateLabel(slotOf(b.slot).date)}} · {{slotOf(b.slot).time}}</td><td>{{slotOf(b.slot).mode}}<br>{{slotOf(b.slot).price.toLocaleString(locale())}} {{ t("تومان") }}</td><td class="wrap-cell">{{b.note||'—'}}</td><td><span class="status-pill">{{ t(statusLabel(b.status)) }}</span><div v-if="b.status==='confirmed'" class="booking-admin-actions"><button @click="b.status='completed'">{{ t("انجام شد") }}</button><button @click="cancel(b.id)">{{ t("لغو رزرو") }}</button></div></td></tr></tbody></table></div><p v-if="!bookings.length" class="empty-state">{{ t("نوبتی با این مشخصات وجود ندارد. فیلترها را تغییر دهید.") }}</p></section></template>
<section v-if="tab==='doctors'" class="ops-panel"><div class="doctor-grid"><article v-for="d in doctors" :key="d.id" class="doctor-card"><div class="doctor-avatar">✳</div><div><h3>{{ t(d.name) }}</h3><span>{{ t(d.specialty) }}</span><p>{{ t(d.bio) }}</p><small>{{ t(d.active?'فعال و قابل رزرو':'غیرفعال') }}</small><div class="booking-admin-actions"><button @click="editDoctor(d)">{{ t("ویرایش پروفایل") }}</button><button @click="d.active=!d.active">{{ t(d.active?'غیرفعال کردن':'فعال کردن') }}</button></div></div></article></div><p v-if="!doctors.length" class="empty-state">{{ t("اولین متخصص مجموعه را اضافه کنید.") }}</p></section>
<template v-if="tab==='tickets'"><div class="ops-filters"><label>{{ t("جست‌وجو") }}<input v-model="query" :placeholder="t('نام، موضوع یا کد پیگیری')"/></label><label>{{ t("وضعیت") }}<select v-model="filter"><option value="all">{{ t("همه پیام‌ها") }}</option><option value="new">{{ t("جدید") }}</option><option value="review">{{ t("در حال بررسی") }}</option><option value="closed">{{ t("بسته‌شده") }}</option></select></label></div><section class="ops-panel"><article v-for="ticket in tickets" :key="ticket.id" class="ticket-card"><header><h3>{{ticket.subject}}</h3><select v-model="ticket.status" :aria-label="t('وضعیت تیکت')"><option value="new">{{ t("جدید") }}</option><option value="review">{{ t("در حال بررسی") }}</option><option value="closed">{{ t("بسته‌شده") }}</option></select></header><small>{{ticket.name}} · {{ticket.phone}} · {{ticket.email}} · {{new Date(ticket.created).toLocaleDateString(locale())}} · {{ticket.id.slice(0,8)}}</small><p v-if="ticket.specialty||ticket.organization">{{ticket.specialty}} {{ticket.license}} {{ticket.city}} {{ticket.organization}}</p><p class="ticket-message">{{ticket.message}}</p><label class="field-label">{{ t("پاسخ / یادداشت پیگیری") }}<textarea v-model="ticket.reply" rows="3" :placeholder="t('یادداشت شما به‌صورت خودکار در این مرورگر ذخیره می‌شود؛ ارسال خارجی ندارد.')"/></label></article><p v-if="!tickets.length" class="empty-state">{{ t("پیامی یافت نشد. پیام‌های فرم ارتباط با ما در اینجا نمایش داده می‌شوند.") }}</p></section></template>
</div>
<div v-if="editing" class="modal-backdrop" @click.self="editing=''" @keydown.esc="editing=''"><section class="editor-modal" role="dialog" aria-modal="true" :aria-label="t('ویرایش اطلاعات')"><div class="editor-head"><h2>{{ t(editing==='doctor'?'مشخصات متخصص':'زمان ویزیت') }}</h2><button class="icon-button" @click="editing=''" :aria-label="t('بستن')">×</button></div><form v-if="editing==='doctor'" @submit.prevent="persistDoctor"><div class="form-grid"><label><span>{{ t("نام متخصص *") }}</span><input v-model.trim="doctorForm.name" required/></label><label><span>{{ t("تخصص *") }}</span><input v-model.trim="doctorForm.specialty" required/></label><label class="form-full"><span>{{ t("معرفی") }}</span><textarea v-model.trim="doctorForm.bio" rows="3"/></label><label><span>{{ t("وضعیت") }}</span><select v-model="doctorForm.active"><option :value="true">{{ t("فعال") }}</option><option :value="false">{{ t("غیرفعال") }}</option></select></label></div><button class="button button-primary reserve-button">{{ t("ذخیره متخصص") }}</button></form><form v-else @submit.prevent="persistSlot"><div class="form-grid"><label class="form-full"><span>{{ t("متخصص *") }}</span><select v-model="slotForm.doctor" required><option value="" disabled>{{ t("انتخاب کنید") }}</option><option v-for="d in doctors.filter(d=>d.active)" :value="d.id" :key="d.id">{{ t(d.name) }}</option></select></label><label><span>{{ t("تاریخ *") }}</span><input v-model="slotForm.date" type="date" :min="today()" required/></label><label><span>{{ t("ساعت *") }}</span><input v-model="slotForm.time" type="time" required/></label><label><span>{{ t("مدت (دقیقه)") }}</span><input v-model.number="slotForm.duration" type="number" min="10" max="180" required/></label><label><span>{{ t("هزینه (تومان)") }}</span><input v-model.number="slotForm.price" type="number" min="0" required/></label><label><span>{{ t("نوع ویزیت") }}</span><select v-model="slotForm.mode"><option value="آنلاین">{{ t("آنلاین") }}</option><option value="حضوری">{{ t("حضوری") }}</option><option value="تلفنی">{{ t("تلفنی") }}</option></select></label></div><p role="status">{{ t(notice) }}</p><button class="button button-primary reserve-button">{{ t("ذخیره زمان") }}</button></form></section></div>
</OpsShell>
</template>
